using System;
using System.Globalization;
using System.Threading;
using System.Threading.Tasks;

internal static class Program
{
    private sealed class Node
    {
        private readonly Node? left;
        private readonly Node? right;

        public Node()
        {
        }

        public Node(Node left, Node right)
        {
            this.left = left;
            this.right = right;
        }

        public long Check()
        {
            return left is null
                ? 1L
                : 1L + left.Check() + right!.Check();
        }
    }

    private static Node MakeTree(int depth)
    {
        return depth <= 0
            ? new Node()
            : new Node(MakeTree(depth - 1), MakeTree(depth - 1));
    }

    private static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);
        int stretchDepth = n + 1;

        Node? stretchTree = MakeTree(stretchDepth);
        Console.WriteLine(
            $"stretch tree of depth {stretchDepth}\t check: {stretchTree.Check()}");
        stretchTree = null;

        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();

        Node longLivedTree = MakeTree(n);

        for (int depth = 4; depth <= n; depth += 2)
        {
            int currentDepth = depth;
            int iterations = 1 << (n - currentDepth + 4);
            long checksum = 0;

            Parallel.For(
                0,
                iterations,
                () => 0L,
                (i, state, localChecksum) =>
                    localChecksum + MakeTree(currentDepth).Check(),
                localChecksum => Interlocked.Add(ref checksum, localChecksum));

            Console.WriteLine(
                $"{iterations}\t trees of depth {currentDepth}\t check: {checksum}");
        }

        Console.WriteLine(
            $"long lived tree of depth {n}\t check: {longLivedTree.Check()}");
    }
}
