                {
                    if (data[position] == (byte)'\r')
                    {
                        position++;
                        if (position < length && data[position] == (byte)'\n')
                            position++;
                    }
                    else
                    {
                        position++;
                    }
                }

                sequenceStart = position;
                lineStart = true;
            }
            else
            {
                byte value = data[position++];
                lineStart = value == (byte)'\r' || value == (byte)'\n';
            }
        }

        if (sequenceStart >= 0)
            ReverseComplement(data, sequenceStart, length, complement);

        using Stream output = Console.OpenStandardOutput();
        output.Write(data, 0, length);
    }

    private static byte[] CreateComplementTable()
    {
        var table = new byte[256];

        for (int i = 0; i < table.Length; i++)
            table[i] = (byte)i;

        Add(table, 'A', 'T');
        Add(table, 'T', 'A');
        Add(table, 'C', 'G');
        Add(table, 'G', 'C');
        Add(table, 'U', 'A');
        Add(table, 'R', 'Y');
        Add(table, 'Y', 'R');
        Add(table, 'K', 'M');
        Add(table, 'M', 'K');
        Add(table, 'B', 'V');
        Add(table, 'V', 'B');
        Add(table, 'D', 'H');
        Add(table, 'H', 'D');
        Add(table, 'S', 'S');
        Add(table, 'W', 'W');
        Add(table, 'N', 'N');

        return table;
    }

    private static void Add(byte[] table, char source, char destination)
    {
        table[(byte)source] = (byte)destination;
        table[(byte)char.ToLowerInvariant(source)] = (byte)destination;
    }

    private static void ReverseComplement(
        byte[] data,
        int start,
        int end,
        byte[] complement)
    {
        int left = start;
        int right = end - 1;

        while (true)
        {
            while (left <= right &&
                   (data[left] == (byte)'\r' || data[left] == (byte)'\n'))
            {
                left++;
            }

            while (left <= right &&
                   (data[right] == (byte)'\r' || data[right] == (byte)'\n'))
            {
                right--;
            }

            if (left > right)
                break;

            byte leftValue = data[left];
            byte rightValue = data[right];

            data[left] = complement[rightValue];
            data[right] = complement[leftValue];

            left++;
            right--;
        }
    }
