    private static void MultiplyA(double[] input, double[] output)
    {
        int n = input.Length;

        Parallel.For(0, n, i =>
        {
            double sum = 0.0;
            double denominator = ((double)i * (i + 3) * 0.5) + 1.0;
            double increment = i + 1.0;

            for (int j = 0; j < n; j++)
            {
                sum += input[j] / denominator;
                denominator += increment;
                increment += 1.0;
            }

            output[i] = sum;
        });
    }

