using System;
using System.IO;
using System.Text;
using System.Globalization;

public static class Program
{
    private const int Modulus = 139968;
    private const int Multiplier = 3877;
    private const int Increment = 29573;
    private const int LineWidth = 60;

    private static readonly string Alu =
        "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
        "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
        "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
        "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
        "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], NumberStyles.Integer, CultureInfo.InvariantCulture);

        byte[] iubSymbols = Encoding.ASCII.GetBytes("acgtBDHKMNRSVWY");
        double[] iubProbabilities =
        {
            0.27, 0.12, 0.12, 0.27,
            0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
            0.02, 0.02, 0.02, 0.02, 0.02
        };

        byte[] humanSymbols = Encoding.ASCII.GetBytes("acgt");
        double[] humanProbabilities =
        {
            0.3029549426680,
            0.1979883004921,
            0.1975473066391,
            0.3015094502008
        };

        BuildRandomCycles(
            iubSymbols, iubProbabilities,
            humanSymbols, humanProbabilities,
            out byte[] iubCycle,
            out byte[] humanCycle);

        byte[] aluBytes = ExpandForLineCopies(Encoding.ASCII.GetBytes(Alu));
        iubCycle = ExpandForLineCopies(iubCycle);
        humanCycle = ExpandForLineCopies(humanCycle);

        using Stream output = Console.OpenStandardOutput();
        var writer = new FastaWriter(output);

        writer.WriteHeader(">ONE Homo sapiens alu\n");
        int aluPosition = 0;
        writer.WriteSequence(aluBytes, Alu.Length, 2L * n, ref aluPosition);

        writer.WriteHeader(">TWO IUB ambiguity codes\n");
        int randomPosition = 0;
        writer.WriteSequence(iubCycle, Modulus, 3L * n, ref randomPosition);

        writer.WriteHeader(">THREE Homo sapiens frequency\n");
        writer.WriteSequence(humanCycle, Modulus, 5L * n, ref randomPosition);

        writer.Finish();
    }

    private static void BuildRandomCycles(
        byte[] firstSymbols,
        double[] firstProbabilities,
        byte[] secondSymbols,
        double[] secondProbabilities,
        out byte[] firstCycle,
        out byte[] secondCycle)
    {
        double[] firstCumulative = BuildCumulative(firstProbabilities);
        double[] secondCumulative = BuildCumulative(secondProbabilities);

        firstCycle = new byte[Modulus];
        secondCycle = new byte[Modulus];

        int seed = 42;

        for (int i = 0; i < Modulus; i++)
        {
            seed = (seed * Multiplier + Increment) % Modulus;
            double r = (double)seed / Modulus;

            firstCycle[i] = Select(firstSymbols, firstCumulative, r);
            secondCycle[i] = Select(secondSymbols, secondCumulative, r);
        }
    }

    private static double[] BuildCumulative(double[] probabilities)
    {
        double[] cumulative = new double[probabilities.Length];
        double sum = 0.0;

        for (int i = 0; i < probabilities.Length; i++)
        {
            sum += probabilities[i];
            cumulative[i] = sum;
        }

        return cumulative;
    }

    private static byte Select(byte[] symbols, double[] cumulative, double value)
    {
        for (int i = 0; i < cumulative.Length; i++)
        {
            if (cumulative[i] > value)
                return symbols[i];
        }

        return symbols[symbols.Length - 1];
    }

    private static byte[] ExpandForLineCopies(byte[] source)
    {
        byte[] expanded = new byte[source.Length + LineWidth];
        Buffer.BlockCopy(source, 0, expanded, 0, source.Length);

        for (int i = 0; i < LineWidth; i++)
            expanded[source.Length + i] = source[i % source.Length];

        return expanded;
    }

    private sealed class FastaWriter
    {
        private readonly Stream output;
        private readonly byte[] buffer = new byte[1 << 20];
        private int position;

        public FastaWriter(Stream output)
        {
            this.output = output;
        }

        public void WriteHeader(string header)
        {
            EnsureCapacity(header.Length);
            position += Encoding.ASCII.GetBytes(
                header, 0, header.Length, buffer, position);
        }

        public void WriteSequence(
            byte[] expandedSource,
            int sourceLength,
            long sequenceLength,
            ref int sourcePosition)
        {
            long remaining = sequenceLength;
            int sourceIndex = sourcePosition;

            while (remaining > 0)
            {
                int count = remaining >= LineWidth
                    ? LineWidth
                    : (int)remaining;

                EnsureCapacity(count + 1);

                Buffer.BlockCopy(
                    expandedSource,
                    sourceIndex,
                    buffer,
                    position,
                    count);

                position += count;
                buffer[position++] = (byte)'\n';

                sourceIndex += count;
                if (sourceIndex >= sourceLength)
                    sourceIndex -= sourceLength;

                remaining -= count;
            }

            sourcePosition = sourceIndex;
        }

        public void Finish()
        {
            FlushBuffer();
            output.Flush();
        }

        private void EnsureCapacity(int required)
        {
            if (position + required > buffer.Length)
                FlushBuffer();
        }

        private void FlushBuffer()
        {
            if (position == 0)
                return;

            output.Write(buffer, 0, position);
            position = 0;
        }
    }
}
