using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;

public static class Program
{
    private struct Frequency
    {
        public string Key;
        public long Count;

        public Frequency(string key, long count)
        {
            Key = key;
            Count = count;
        }
    }

    public static void Main(string[] args)
    {
        _ = int.Parse(args[0], CultureInfo.InvariantCulture);

        byte[] sequence = ReadThreeSequence(out int length);

        long[] oneMerCounts = new long[256];
        long[] twoMerCounts = new long[65536];

        for (int i = 0; i < length; i++)
        {
            byte current = sequence[i];
            oneMerCounts[current]++;

            if (i > 0)
            {
                int key = (sequence[i - 1] << 8) | current;
                twoMerCounts[key]++;
            }
        }

        List<Frequency> oneMers = new List<Frequency>();
        for (int i = 0; i < oneMerCounts.Length; i++)
        {
            if (oneMerCounts[i] != 0)
                oneMers.Add(new Frequency(((char)i).ToString(), oneMerCounts[i]));
        }

        List<Frequency> twoMers = new List<Frequency>();
        for (int i = 0; i < twoMerCounts.Length; i++)
        {
            if (twoMerCounts[i] != 0)
            {
                char first = (char)(i >> 8);
                char second = (char)(i & 255);
                twoMers.Add(new Frequency(new string(new[] { first, second }), twoMerCounts[i]));
            }
        }

        Comparison<Frequency> comparison = (x, y) =>
        {
            int byCount = y.Count.CompareTo(x.Count);
            return byCount != 0
                ? byCount
                : string.CompareOrdinal(y.Key, x.Key);
        };

        oneMers.Sort(comparison);
        twoMers.Sort(comparison);

        long[] fragmentCounts = CountFragments(sequence, length);
        string[] fragments =
        {
            "GGT",
            "GGTA",
            "GGTATT",
            "GGTATTTTAATT",
            "GGTATTTTAATTTATAGT"
        };

        CultureInfo invariant = CultureInfo.InvariantCulture;
        StringBuilder output = new StringBuilder();

        AppendFrequencies(output, oneMers, length, invariant);
        output.Append('\n');

        AppendFrequencies(output, twoMers, Math.Max(0, length - 1), invariant);
        output.Append('\n');

        for (int i = 0; i < fragments.Length; i++)
        {
            output.Append(fragmentCounts[i].ToString(invariant))
                  .Append('\t')
                  .Append(fragments[i])
                  .Append('\n');
        }

        Console.Write(output.ToString());
    }

    private static void AppendFrequencies(
        StringBuilder output,
        List<Frequency> frequencies,
        int total,
        CultureInfo culture)
    {
        foreach (Frequency frequency in frequencies)
        {
            double percentage = total == 0
                ? 0.0
                : frequency.Count * 100.0 / total;

            output.Append(frequency.Key)
                  .Append(' ')
                  .Append(percentage.ToString("F3", culture))
                  .Append('\n');
        }
    }

    private static long[] CountFragments(byte[] sequence, int length)
    {
        long[] counts = new long[5];

        for (int i = 0; i + 2 < length; i++)
        {
            if (sequence[i] != (byte)'G' ||
                sequence[i + 1] != (byte)'G' ||
                sequence[i + 2] != (byte)'T')
            {
                continue;
            }

            counts[0]++;

            if (i + 3 >= length || sequence[i + 3] != (byte)'A')
                continue;

            counts[1]++;

            if (i + 5 >= length ||
                sequence[i + 4] != (byte)'T' ||
                sequence[i + 5] != (byte)'T')
            {
                continue;
            }

            counts[2]++;

            if (i + 11 >= length ||
                sequence[i + 6] != (byte)'T' ||
                sequence[i + 7] != (byte)'T' ||
                sequence[i + 8] != (byte)'A' ||
                sequence[i + 9] != (byte)'A' ||
                sequence[i + 10] != (byte)'T' ||
                sequence[i + 11] != (byte)'T')
            {
                continue;
            }

            counts[3]++;

            if (i + 17 >= length ||
                sequence[i + 12] != (byte)'T' ||
                sequence[i + 13] != (byte)'A' ||
                sequence[i + 14] != (byte)'T' ||
                sequence[i + 15] != (byte)'A' ||
                sequence[i + 16] != (byte)'G' ||
                sequence[i + 17] != (byte)'T')
            {
                continue;
            }

            counts[4]++;
        }

        return counts;
    }

    private static byte[] ReadThreeSequence(out int length)
    {
        Stream input = Console.OpenStandardInput();
        byte[] readBuffer = new byte[65536];
        byte[] sequence = new byte[1 << 20];
        byte[] targetName = Encoding.ASCII.GetBytes("THREE");

        length = 0;

        bool inTarget = false;
        bool inHeader = false;
        bool atLineStart = true;
        bool tokenValid = true;
        bool tokenEnded = false;
        bool finished = false;
        int tokenPosition = 0;

        while (!finished)
        {
            int bytesRead = input.Read(readBuffer, 0, readBuffer.Length);
            if (bytesRead == 0)
                break;

            for (int i = 0; i < bytesRead; i++)
            {
                byte value = readBuffer[i];

                if (inHeader)
                {
                    if (value == (byte)'\n')
                    {
                        inHeader = false;
                        atLineStart = true;
                        inTarget = tokenValid && tokenPosition == targetName.Length;
                        continue;
                    }

                    if (value == (byte)'\r' ||
                        value == (byte)' ' ||
                        value == (byte)'\t')
                    {
                        tokenEnded = true;
                        continue;
                    }

                    if (tokenEnded)
                        continue;

                    if (tokenPosition >= targetName.Length ||
                        value != targetName[tokenPosition])
                    {
                        tokenValid = false;
                    }

                    tokenPosition++;
                    continue;
                }

                if (atLineStart && value == (byte)'>')
                {
                    if (inTarget)
                    {
                        finished = true;
                        break;
                    }

                    inHeader = true;
                    atLineStart = false;
                    tokenValid = true;
                    tokenEnded = false;
                    tokenPosition = 0;
                    continue;
                }

                if (value == (byte)'\n')
                {
                    atLineStart = true;
                    continue;
                }

                if (value == (byte)'\r')
                    continue;

                atLineStart = false;

                if (!inTarget || value <= (byte)' ')
                    continue;

                if (value >= (byte)'a' && value <= (byte)'z')
                    value = (byte)(value - ('a' - 'A'));

                if (length == sequence.Length)
                    Array.Resize(ref sequence, sequence.Length * 2);

                sequence[length++] = value;
            }
        }

        return sequence;
    }
}
