using System.Runtime.CompilerServices;

public static class Program
{
    private const double DaysPerYear = 365.24;
    private static readonly double SolarMass = 4.0 * Math.PI * Math.PI;

    private sealed class Body
    {
        public double X;
        public double Y;
        public double Z;
        public double Vx;
        public double Vy;
        public double Vz;
        public double Mass;

        public Body(
            double x, double y, double z,
            double vx, double vy, double vz,
            double mass)
        {
            X = x;
            Y = y;
            Z = z;
            Vx = vx;
            Vy = vy;
            Vz = vz;
            Mass = mass;
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Interact(Body a, Body b, double dt)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        double dz = a.Z - b.Z;

        double distanceSquared = dx * dx + dy * dy + dz * dz;
        double magnitude = dt / (distanceSquared * Math.Sqrt(distanceSquared));

        a.Vx -= dx * b.Mass * magnitude;
        a.Vy -= dy * b.Mass * magnitude;
        a.Vz -= dz * b.Mass * magnitude;

        b.Vx += dx * a.Mass * magnitude;
        b.Vy += dy * a.Mass * magnitude;
        b.Vz += dz * a.Mass * magnitude;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Move(Body body, double dt)
    {
        body.X += dt * body.Vx;
        body.Y += dt * body.Vy;
        body.Z += dt * body.Vz;
    }

    private static void Advance(
        Body sun,
        Body jupiter,
        Body saturn,
        Body uranus,
        Body neptune,
        int steps)
    {
        const double dt = 0.01;

        for (int i = 0; i < steps; i++)
        {
            Interact(sun, jupiter, dt);
            Interact(sun, saturn, dt);
            Interact(sun, uranus, dt);
            Interact(sun, neptune, dt);

            Interact(jupiter, saturn, dt);
            Interact(jupiter, uranus, dt);
            Interact(jupiter, neptune, dt);

            Interact(saturn, uranus, dt);
            Interact(saturn, neptune, dt);

            Interact(uranus, neptune, dt);

            Move(sun, dt);
            Move(jupiter, dt);
            Move(saturn, dt);
            Move(uranus, dt);
            Move(neptune, dt);
        }
    }

    private static double Energy(Body[] bodies)
    {
        double energy = 0.0;

        for (int i = 0; i < bodies.Length; i++)
        {
            Body a = bodies[i];

            energy += 0.5 * a.Mass *
                      (a.Vx * a.Vx + a.Vy * a.Vy + a.Vz * a.Vz);

            for (int j = i + 1; j < bodies.Length; j++)
            {
                Body b = bodies[j];

                double dx = a.X - b.X;
                double dy = a.Y - b.Y;
                double dz = a.Z - b.Z;

                double distance = Math.Sqrt(dx * dx + dy * dy + dz * dz);
                energy -= (a.Mass * b.Mass) / distance;
            }
        }

        return energy;
    }

    private static void OffsetMomentum(Body[] bodies)
    {
        double px = 0.0;
        double py = 0.0;
        double pz = 0.0;

        for (int i = 0; i < bodies.Length; i++)
        {
            Body body = bodies[i];
            px += body.Vx * body.Mass;
            py += body.Vy * body.Mass;
            pz += body.Vz * body.Mass;
        }

        bodies[0].Vx = -px / SolarMass;
        bodies[0].Vy = -py / SolarMass;
        bodies[0].Vz = -pz / SolarMass;
    }

